package filter

import (
	"context"
	"strings"
	"sync"
	"time"

	"github.com/google/cel-go/cel"
	"github.com/pkg/errors"
)

// Engine parses CEL filters into a dialect-agnostic condition tree.
type Engine struct {
	schema Schema
	env    *cel.Env
	// nowFunc resolves the value of the `now` variable. It is frozen once per
	// Compile so a single filter sees a single instant, and is overridable in
	// tests for deterministic folding.
	nowFunc func() time.Time
}

// NewEngine builds a new Engine for the provided schema.
func NewEngine(schema Schema) (*Engine, error) {
	env, err := cel.NewEnv(schema.EnvOptions...)
	if err != nil {
		return nil, errors.Wrap(err, "failed to create CEL environment")
	}
	return &Engine{
		schema:  schema,
		env:     env,
		nowFunc: time.Now,
	}, nil
}

// Program stores a compiled filter condition.
type Program struct {
	schema    Schema
	condition Condition
}

// ConditionTree exposes the underlying condition tree.
func (p *Program) ConditionTree() Condition {
	return p.condition
}

// Compile parses the filter string into an executable program.
func (e *Engine) Compile(_ context.Context, filter string) (*Program, error) {
	if strings.TrimSpace(filter) == "" {
		return nil, errors.New("filter expression is empty")
	}

	ast, issues := e.env.Compile(filter)
	if issues != nil && issues.Err() != nil {
		return nil, errors.Wrap(issues.Err(), "failed to compile filter")
	}
	parsed, err := cel.AstToParsedExpr(ast)
	if err != nil {
		return nil, errors.Wrap(err, "failed to convert AST")
	}

	cond, err := buildCondition(parsed.GetExpr(), parseContext{schema: e.schema, now: e.nowFunc()})
	if err != nil {
		return nil, err
	}

	return &Program{
		schema:    e.schema,
		condition: cond,
	}, nil
}

// CompileToStatement compiles and renders the filter in a single step.
func (e *Engine) CompileToStatement(ctx context.Context, filter string, opts RenderOptions) (Statement, error) {
	program, err := e.Compile(ctx, filter)
	if err != nil {
		return Statement{}, err
	}
	return program.Render(opts)
}

// RenderOptions configure SQL rendering.
type RenderOptions struct {
	Dialect           DialectName
	PlaceholderOffset int
	DisableNullChecks bool
}

// Statement contains the rendered SQL fragment and its args.
type Statement struct {
	SQL  string
	Args []any
}

// Render converts the program into a dialect-specific SQL fragment.
func (p *Program) Render(opts RenderOptions) (Statement, error) {
	renderer := newRenderer(p.schema, opts)
	return renderer.Render(p.condition)
}

var (
	defaultOnce           sync.Once
	defaultInst           *Engine
	defaultErr            error
	defaultAttachmentOnce sync.Once
	defaultAttachmentInst *Engine
	defaultAttachmentErr  error
)

// DefaultEngine returns the process-wide memo filter engine.
func DefaultEngine() (*Engine, error) {
	defaultOnce.Do(func() {
		defaultInst, defaultErr = NewEngine(NewSchema())
	})
	return defaultInst, defaultErr
}

// DefaultAttachmentEngine returns the process-wide attachment filter engine.
func DefaultAttachmentEngine() (*Engine, error) {
	defaultAttachmentOnce.Do(func() {
		defaultAttachmentInst, defaultAttachmentErr = NewEngine(NewAttachmentSchema())
	})
	return defaultAttachmentInst, defaultAttachmentErr
}

package store

import (
	"context"
	"errors"

	"github.com/usememos/memos/internal/base"

	storepb "github.com/usememos/memos/proto/gen/store"
)

// Visibility is the type of a visibility.
type Visibility string

const (
	// Public is the PUBLIC visibility.
	Public Visibility = "PUBLIC"
	// Protected is the PROTECTED visibility.
	Protected Visibility = "PROTECTED"
	// Private is the PRIVATE visibility.
	Private Visibility = "PRIVATE"
)

func (v Visibility) String() string {
	switch v {
	case Public:
		return "PUBLIC"
	case Protected:
		return "PROTECTED"
	default:
		return "PRIVATE"
	}
}

type Memo struct {
	// ID is the system generated unique identifier for the memo.
	ID int32
	// UID is the user defined unique identifier for the memo.
	UID string

	// Standard fields
	RowStatus RowStatus
	CreatorID int32
	CreatedTs int64
	UpdatedTs int64

	// Domain specific fields
	Content    string
	Visibility Visibility
	Pinned     bool
	Payload    *storepb.MemoPayload

	// Composed fields
	ParentUID *string
}

type FindMemo struct {
	ID  *int32
	UID *string

	IDList  []int32
	UIDList []string

	// Standard fields
	RowStatus *RowStatus
	CreatorID *int32

	// Domain specific fields
	VisibilityList  []Visibility
	ExcludeContent  bool
	ExcludeComments bool
	Filters         []string

	// Pagination
	Limit  *int
	Offset *int

	// Ordering
	OrderByPinned    bool
	OrderByUpdatedTs bool
	OrderByTimeAsc   bool
}

type FindMemoPayload struct {
	Raw                *string
	TagSearch          []string
	HasLink            bool
	HasTaskList        bool
	HasCode            bool
	HasIncompleteTasks bool
}

type UpdateMemo struct {
	ID         int32
	UID        *string
	CreatedTs  *int64
	UpdatedTs  *int64
	RowStatus  *RowStatus
	Content    *string
	Visibility *Visibility
	Pinned     *bool
	Payload    *storepb.MemoPayload
}

type DeleteMemo struct {
	ID int32
}

func (s *Store) CreateMemo(ctx context.Context, create *Memo) (*Memo, error) {
	if !base.UIDMatcher.MatchString(create.UID) {
		return nil, errors.New("invalid uid")
	}
	return s.driver.CreateMemo(ctx, create)
}

func (s *Store) ListMemos(ctx context.Context, find *FindMemo) ([]*Memo, error) {
	return s.driver.ListMemos(ctx, find)
}

func (s *Store) GetMemo(ctx context.Context, find *FindMemo) (*Memo, error) {
	list, err := s.ListMemos(ctx, find)
	if err != nil {
		return nil, err
	}
	if len(list) == 0 {
		return nil, nil
	}

	memo := list[0]
	return memo, nil
}

func (s *Store) UpdateMemo(ctx context.Context, update *UpdateMemo) error {
	if update.UID != nil && !base.UIDMatcher.MatchString(*update.UID) {
		return errors.New("invalid uid")
	}
	return s.driver.UpdateMemo(ctx, update)
}

func (s *Store) DeleteMemo(ctx context.Context, delete *DeleteMemo) error {
	// Clean up memo_relation records where this memo is either the source or target.
	if err := s.driver.DeleteMemoRelation(ctx, &DeleteMemoRelation{MemoID: &delete.ID}); err != nil {
		return err
	}
	if err := s.driver.DeleteMemoRelation(ctx, &DeleteMemoRelation{RelatedMemoID: &delete.ID}); err != nil {
		return err
	}
	// Clean up attachments linked to this memo.
	attachments, err := s.ListAttachments(ctx, &FindAttachment{MemoID: &delete.ID})
	if err != nil {
		return err
	}
	for _, attachment := range attachments {
		if err := s.DeleteAttachment(ctx, &DeleteAttachment{ID: attachment.ID}); err != nil {
			return err
		}
	}
	return s.driver.DeleteMemo(ctx, delete)
}

package v1

import (
	"strings"

	"github.com/pkg/errors"

	"github.com/usememos/memos/store"
)

func (*APIV1Service) parseMemoOrderBy(orderBy string, memoFind *store.FindMemo) error {
	if strings.TrimSpace(orderBy) == "" {
		return errors.New("empty order_by")
	}

	// Split by comma to support multiple sort fields per AIP-132.
	fields := strings.Split(orderBy, ",")

	// Track if we've seen pinned field.
	hasPinned := false
	hasExplicitTimeField := false

	for _, field := range fields {
		parts := strings.Fields(strings.TrimSpace(field))
		if len(parts) == 0 {
			continue
		}

		fieldName := parts[0]
		fieldDirection := "desc" // default per AIP-132 (we use desc as default for time fields)
		if len(parts) > 1 {
			fieldDirection = strings.ToLower(parts[1])
			if fieldDirection != "asc" && fieldDirection != "desc" {
				return errors.Errorf("invalid order direction: %s, must be 'asc' or 'desc'", parts[1])
			}
		}

		switch fieldName {
		case "pinned":
			hasPinned = true
			memoFind.OrderByPinned = true
			// Note: pinned is always DESC (true first) regardless of direction specified.
		case "create_time", "name":
			// Only set if this is the first time field we encounter.
			if !hasExplicitTimeField {
				memoFind.OrderByTimeAsc = fieldDirection == "asc"
			}
			hasExplicitTimeField = true
		case "update_time":
			// Only set if this is the first time field we encounter.
			if !hasExplicitTimeField {
				memoFind.OrderByUpdatedTs = true
				memoFind.OrderByTimeAsc = fieldDirection == "asc"
			}
			hasExplicitTimeField = true
		default:
			return errors.Errorf("unsupported order field: %s, supported fields are: pinned, create_time, update_time, name", fieldName)
		}
	}

	// If only pinned was specified, still need to set a default time ordering.
	if hasPinned && !memoFind.OrderByUpdatedTs && len(fields) == 1 {
		memoFind.OrderByTimeAsc = false // default to desc
	}

	return nil
}

package filter

import (
	"context"
	"fmt"
)

// AppendConditions compiles the provided filters and appends the resulting SQL fragments and args.
func AppendConditions(ctx context.Context, engine *Engine, filters []string, dialect DialectName, where *[]string, args *[]any) error {
	for _, filterStr := range filters {
		stmt, err := engine.CompileToStatement(ctx, filterStr, RenderOptions{
			Dialect:           dialect,
			PlaceholderOffset: len(*args),
		})
		if err != nil {
			return err
		}
		if stmt.SQL == "" {
			continue
		}
		*where = append(*where, fmt.Sprintf("(%s)", stmt.SQL))
		*args = append(*args, stmt.Args...)
	}
	return nil
}

package filter

import (
	"fmt"

	"github.com/google/cel-go/cel"
	"github.com/google/cel-go/ext"
)

// DialectName enumerates supported SQL dialects.
type DialectName string

const (
	DialectSQLite   DialectName = "sqlite"
	DialectMySQL    DialectName = "mysql"
	DialectPostgres DialectName = "postgres"
)

// FieldType represents the logical type of a field.
type FieldType string

const (
	FieldTypeString    FieldType = "string"
	FieldTypeInt       FieldType = "int"
	FieldTypeBool      FieldType = "bool"
	FieldTypeTimestamp FieldType = "timestamp"
)

// FieldKind describes how a field is stored.
type FieldKind string

const (
	FieldKindScalar       FieldKind = "scalar"
	FieldKindBoolColumn   FieldKind = "bool_column"
	FieldKindJSONBool     FieldKind = "json_bool"
	FieldKindJSONList     FieldKind = "json_list"
	FieldKindVirtualAlias FieldKind = "virtual_alias"
)

// Column identifies the backing table column.
type Column struct {
	Table string
	Name  string
}

// Field captures the schema metadata for an exposed CEL identifier.
type Field struct {
	Name                 string
	Kind                 FieldKind
	Type                 FieldType
	Column               Column
	JSONPath             []string
	AliasFor             string
	SupportsContains     bool
	Expressions          map[DialectName]string
	AllowedComparisonOps map[ComparisonOperator]bool
}

// Schema collects CEL environment options and field metadata.
type Schema struct {
	Name       string
	Fields     map[string]Field
	EnvOptions []cel.EnvOption
}

// Field returns the field metadata if present.
func (s Schema) Field(name string) (Field, bool) {
	f, ok := s.Fields[name]
	return f, ok
}

// ResolveAlias resolves a virtual alias to its target field.
func (s Schema) ResolveAlias(name string) (Field, bool) {
	field, ok := s.Fields[name]
	if !ok {
		return Field{}, false
	}
	if field.Kind == FieldKindVirtualAlias {
		target, ok := s.Fields[field.AliasFor]
		if !ok {
			return Field{}, false
		}
		return target, true
	}
	return field, true
}

// NewSchema constructs the memo filter schema and CEL environment.
func NewSchema() Schema {
	fields := map[string]Field{
		"content": {
			Name:             "content",
			Kind:             FieldKindScalar,
			Type:             FieldTypeString,
			Column:           Column{Table: "memo", Name: "content"},
			SupportsContains: true,
			Expressions:      map[DialectName]string{},
		},
		"creator": {
			Name:   "creator",
			Kind:   FieldKindScalar,
			Type:   FieldTypeString,
			Column: Column{Table: "memo_creator", Name: "username"},
			Expressions: map[DialectName]string{
				DialectSQLite:   "('users/' || %s)",
				DialectMySQL:    "CONCAT('users/', %s)",
				DialectPostgres: "('users/' || %s)",
			},
			AllowedComparisonOps: map[ComparisonOperator]bool{
				CompareEq:  true,
				CompareNeq: true,
			},
		},
		"creator_id": {
			Name:        "creator_id",
			Kind:        FieldKindScalar,
			Type:        FieldTypeInt,
			Column:      Column{Table: "memo", Name: "creator_id"},
			Expressions: map[DialectName]string{},
			AllowedComparisonOps: map[ComparisonOperator]bool{
				CompareEq:  true,
				CompareNeq: true,
			},
		},
		"created_ts": {
			Name:   "created_ts",
			Kind:   FieldKindScalar,
			Type:   FieldTypeTimestamp,
			Column: Column{Table: "memo", Name: "created_ts"},
			Expressions: map[DialectName]string{
				// MySQL stores created_ts as TIMESTAMP, needs conversion to epoch
				DialectMySQL: "UNIX_TIMESTAMP(%s)",
				// PostgreSQL and SQLite store created_ts as BIGINT (epoch), no conversion needed
				DialectPostgres: "%s",
				DialectSQLite:   "%s",
			},
		},
		"updated_ts": {
			Name:   "updated_ts",
			Kind:   FieldKindScalar,
			Type:   FieldTypeTimestamp,
			Column: Column{Table: "memo", Name: "updated_ts"},
			Expressions: map[DialectName]string{
				// MySQL stores updated_ts as TIMESTAMP, needs conversion to epoch
				DialectMySQL: "UNIX_TIMESTAMP(%s)",
				// PostgreSQL and SQLite store updated_ts as BIGINT (epoch), no conversion needed
				DialectPostgres: "%s",
				DialectSQLite:   "%s",
			},
		},
		"pinned": {
			Name:        "pinned",
			Kind:        FieldKindBoolColumn,
			Type:        FieldTypeBool,
			Column:      Column{Table: "memo", Name: "pinned"},
			Expressions: map[DialectName]string{},
			AllowedComparisonOps: map[ComparisonOperator]bool{
				CompareEq:  true,
				CompareNeq: true,
			},
		},
		"visibility": {
			Name:        "visibility",
			Kind:        FieldKindScalar,
			Type:        FieldTypeString,
			Column:      Column{Table: "memo", Name: "visibility"},
			Expressions: map[DialectName]string{},
			AllowedComparisonOps: map[ComparisonOperator]bool{
				CompareEq:  true,
				CompareNeq: true,
			},
		},
		"tags": {
			Name:     "tags",
			Kind:     FieldKindJSONList,
			Type:     FieldTypeString,
			Column:   Column{Table: "memo", Name: "payload"},
			JSONPath: []string{"tags"},
		},
		"tag": {
			Name:     "tag",
			Kind:     FieldKindVirtualAlias,
			Type:     FieldTypeString,
			AliasFor: "tags",
		},
		"has_task_list": {
			Name:     "has_task_list",
			Kind:     FieldKindJSONBool,
			Type:     FieldTypeBool,
			Column:   Column{Table: "memo", Name: "payload"},
			JSONPath: []string{"property", "hasTaskList"},
			AllowedComparisonOps: map[ComparisonOperator]bool{
				CompareEq:  true,
				CompareNeq: true,
			},
		},
		"has_link": {
			Name:     "has_link",
			Kind:     FieldKindJSONBool,
			Type:     FieldTypeBool,
			Column:   Column{Table: "memo", Name: "payload"},
			JSONPath: []string{"property", "hasLink"},
			AllowedComparisonOps: map[ComparisonOperator]bool{
				CompareEq:  true,
				CompareNeq: true,
			},
		},
		"has_code": {
			Name:     "has_code",
			Kind:     FieldKindJSONBool,
			Type:     FieldTypeBool,
			Column:   Column{Table: "memo", Name: "payload"},
			JSONPath: []string{"property", "hasCode"},
			AllowedComparisonOps: map[ComparisonOperator]bool{
				CompareEq:  true,
				CompareNeq: true,
			},
		},
		"has_incomplete_tasks": {
			Name:     "has_incomplete_tasks",
			Kind:     FieldKindJSONBool,
			Type:     FieldTypeBool,
			Column:   Column{Table: "memo", Name: "payload"},
			JSONPath: []string{"property", "hasIncompleteTasks"},
			AllowedComparisonOps: map[ComparisonOperator]bool{
				CompareEq:  true,
				CompareNeq: true,
			},
		},
	}

	envOptions := []cel.EnvOption{
		cel.Variable("content", cel.StringType),
		cel.Variable("creator", cel.StringType),
		cel.Variable("creator_id", cel.IntType),
		cel.Variable("created_ts", cel.TimestampType),
		cel.Variable("updated_ts", cel.TimestampType),
		cel.Variable("pinned", cel.BoolType),
		cel.Variable("tag", cel.StringType),
		cel.Variable("tags", cel.ListType(cel.StringType)),
		cel.Variable("visibility", cel.StringType),
		cel.Variable("has_task_list", cel.BoolType),
		cel.Variable("has_link", cel.BoolType),
		cel.Variable("has_code", cel.BoolType),
		cel.Variable("has_incomplete_tasks", cel.BoolType),
		cel.Variable("now", cel.TimestampType),
		ext.Sets(),
		cel.ASTValidators(cel.ValidateRegexLiterals()),
	}

	return Schema{
		Name:       "memo",
		Fields:     fields,
		EnvOptions: envOptions,
	}
}

// NewAttachmentSchema constructs the attachment filter schema and CEL environment.
func NewAttachmentSchema() Schema {
	fields := map[string]Field{
		"filename": {
			Name:             "filename",
			Kind:             FieldKindScalar,
			Type:             FieldTypeString,
			Column:           Column{Table: "attachment", Name: "filename"},
			SupportsContains: true,
			Expressions:      map[DialectName]string{},
		},
		"mime_type": {
			Name:             "mime_type",
			Kind:             FieldKindScalar,
			Type:             FieldTypeString,
			Column:           Column{Table: "attachment", Name: "type"},
			SupportsContains: true,
			Expressions:      map[DialectName]string{},
		},
		"create_time": {
			Name:   "create_time",
			Kind:   FieldKindScalar,
			Type:   FieldTypeTimestamp,
			Column: Column{Table: "attachment", Name: "created_ts"},
			Expressions: map[DialectName]string{
				// MySQL stores created_ts as TIMESTAMP, needs conversion to epoch
				DialectMySQL: "UNIX_TIMESTAMP(%s)",
				// PostgreSQL and SQLite store created_ts as BIGINT (epoch), no conversion needed
				DialectPostgres: "%s",
				DialectSQLite:   "%s",
			},
		},
		"memo_id": {
			Name:        "memo_id",
			Kind:        FieldKindScalar,
			Type:        FieldTypeInt,
			Column:      Column{Table: "attachment", Name: "memo_id"},
			Expressions: map[DialectName]string{},
			AllowedComparisonOps: map[ComparisonOperator]bool{
				CompareEq:  true,
				CompareNeq: true,
			},
		},
	}

	envOptions := []cel.EnvOption{
		cel.Variable("filename", cel.StringType),
		cel.Variable("mime_type", cel.StringType),
		cel.Variable("create_time", cel.TimestampType),
		cel.Variable("memo_id", cel.AnyType),
		cel.Variable("now", cel.TimestampType),
		cel.ASTValidators(cel.ValidateRegexLiterals()),
	}

	return Schema{
		Name:       "attachment",
		Fields:     fields,
		EnvOptions: envOptions,
	}
}

// columnExpr returns the field expression for the given dialect, applying
// any schema-specific overrides (e.g. UNIX timestamp conversions).
func (f Field) columnExpr(d DialectName) string {
	base := qualifyColumn(d, f.Column)
	if expr, ok := f.Expressions[d]; ok && expr != "" {
		return fmt.Sprintf(expr, base)
	}
	return base
}

package v1

import (
	"context"
	stderrors "errors"
	"fmt"
	"log/slog"
	"strings"
	"time"

	"github.com/pkg/errors"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	"google.golang.org/protobuf/types/known/emptypb"

	"github.com/usememos/memos/internal/httpgetter"
	v1pb "github.com/usememos/memos/proto/gen/api/v1"
	"github.com/usememos/memos/server/runner/memopayload"
	"github.com/usememos/memos/store"
)

// suppressSSEKey is a context key used to suppress the SSE broadcast from
// CreateMemo when it is called internally (e.g., from CreateMemoComment).
type suppressSSEKey struct{}

const maxBatchGetLinkMetadata = 10

var fetchHTMLMeta = httpgetter.GetHTMLMeta

func withSuppressSSE(ctx context.Context) context.Context {
	return context.WithValue(ctx, suppressSSEKey{}, true)
}

func isSSESuppressed(ctx context.Context) bool {
	v, ok := ctx.Value(suppressSSEKey{}).(bool)
	return ok && v
}

func (s *APIV1Service) checkMemoReadAccess(ctx context.Context, memo *store.Memo) error {
	if memo == nil {
		return status.Errorf(codes.NotFound, "memo not found")
	}

	// Archived memos are only visible to their creator.
	if memo.RowStatus == store.Archived {
		user, err := s.fetchCurrentUser(ctx)
		if err != nil {
			return status.Errorf(codes.Internal, "failed to get user")
		}
		if user == nil || memo.CreatorID != user.ID {
			return status.Errorf(codes.NotFound, "memo not found")
		}
	}

	if memo.Visibility != store.Public {
		user, err := s.fetchCurrentUser(ctx)
		if err != nil {
			return status.Errorf(codes.Internal, "failed to get user")
		}
		if user == nil {
			return status.Errorf(codes.Unauthenticated, "user not authenticated")
		}
		if memo.Visibility == store.Private && memo.CreatorID != user.ID {
			return status.Errorf(codes.PermissionDenied, "permission denied")
		}
	}
	return nil
}

func (s *APIV1Service) CreateMemo(ctx context.Context, request *v1pb.CreateMemoRequest) (*v1pb.Memo, error) {
	user, err := s.fetchCurrentUser(ctx)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get user")
	}
	if user == nil {
		return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
	}

	memoUID, err := ValidateAndGenerateUID(request.MemoId)
	if err != nil {
		return nil, err
	}

	create := &store.Memo{
		UID:        memoUID,
		CreatorID:  user.ID,
		Content:    request.Memo.Content,
		Visibility: convertVisibilityToStore(request.Memo.Visibility),
	}

	// Set custom timestamps if provided in the request.
	if request.Memo.CreateTime != nil && request.Memo.CreateTime.IsValid() {
		createdTs := request.Memo.CreateTime.AsTime().Unix()
		create.CreatedTs = createdTs
	}
	if request.Memo.UpdateTime != nil && request.Memo.UpdateTime.IsValid() {
		updatedTs := request.Memo.UpdateTime.AsTime().Unix()
		create.UpdatedTs = updatedTs
	}

	contentLengthLimit, err := s.getContentLengthLimit(ctx)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get content length limit")
	}
	if len(create.Content) > contentLengthLimit {
		return nil, status.Errorf(codes.InvalidArgument, "content too long (max %d characters)", contentLengthLimit)
	}
	if err := memopayload.RebuildMemoPayload(ctx, create, s.MarkdownService); err != nil {
		return nil, status.Errorf(codes.Internal, "failed to rebuild memo payload: %v", err)
	}
	if request.Memo.Location != nil {
		create.Payload.Location = convertLocationToStore(request.Memo.Location)
	}

	memo, err := s.Store.CreateMemo(ctx, create)
	if err != nil {
		// Check for unique constraint violation (AIP-133 compliance)
		errMsg := err.Error()
		if strings.Contains(errMsg, "UNIQUE constraint failed") ||
			strings.Contains(errMsg, "duplicate key") ||
			strings.Contains(errMsg, "Duplicate entry") {
			return nil, status.Errorf(codes.AlreadyExists, "memo with ID %q already exists", memoUID)
		}
		return nil, err
	}

	attachments := []*store.Attachment{}

	if len(request.Memo.Attachments) > 0 {
		if err := s.setMemoAttachmentsInternal(ctx, user, memo, request.Memo.Attachments); err != nil {
			return nil, errors.Wrap(err, "failed to set memo attachments")
		}

		a, err := s.Store.ListAttachments(ctx, &store.FindAttachment{
			MemoID: &memo.ID,
		})
		if err != nil {
			return nil, errors.Wrap(err, "failed to get memo attachments")
		}
		attachments = a
	}
	if len(request.Memo.Relations) > 0 {
		if err := s.setMemoRelationsInternal(ctx, memo, request.Memo.Relations); err != nil {
			return nil, errors.Wrap(err, "failed to set memo relations")
		}
	}

	relations, err := s.loadMemoRelations(ctx, memo)
	if err != nil {
		return nil, errors.Wrap(err, "failed to load memo relations")
	}
	memoMessage, err := s.convertMemoFromStore(ctx, memo, nil, attachments, relations)
	if err != nil {
		return nil, errors.Wrap(err, "failed to convert memo")
	}
	// Try to dispatch webhook when memo is created.
	if err := s.DispatchMemoCreatedWebhook(ctx, memoMessage); err != nil {
		slog.Warn("Failed to dispatch memo created webhook", slog.Any("err", err))
	}

	// Broadcast live refresh event (skipped when called from CreateMemoComment).
	if !isSSESuppressed(ctx) {
		s.SSEHub.Broadcast(&SSEEvent{
			Type:       SSEEventMemoCreated,
			Name:       memoMessage.Name,
			Visibility: memo.Visibility,
			CreatorID:  resolveSSECreatorID(memo, nil),
		})
	}

	if !isMentionNotificationSuppressed(ctx) {
		s.dispatchMemoMentionNotificationsBestEffort(ctx, memo, nil, "")
	}

	return memoMessage, nil
}

